import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:__PKG__/features/scoreboard/scoreboard_controller.dart';

void main() {
  test('minus lowers the score', () {
    final c = ProviderContainer();
    addTearDown(c.dispose);
    c.read(scoreboardProvider.notifier).change(0, 1);
    c.read(scoreboardProvider.notifier).change(0, -1);
    expect(c.read(scoreboardProvider)[0].score, 0);
  });
}

import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:__PKG__/features/scoreboard/scoreboard_controller.dart';

void main() {
  test('reset sets every score to zero', () {
    final c = ProviderContainer();
    addTearDown(c.dispose);
    final n = c.read(scoreboardProvider.notifier);
    n.change(0, 5);
    n.change(1, 3);
    n.reset();
    expect(c.read(scoreboardProvider).map((p) => p.score), everyElement(0));
  });
}
